/**
 * Render-phase conformance with the full default configuration
 * (typography + hyphenation enabled): process() output must match the
 * reference implementation byte-for-byte.
 *
 * Expected HTML generated by tools/transform-oracle.php --render-full
 * --emoticon. Typography patterns live in src/Typography.js;
 * hyphenation is a straight port. Sources with known library divergences
 * are skipped with justification.
 */

import { renderConformance } from "./helpers/render-conformance.js";
import { Syntax } from "../src/Syntax.js";

const knownDivergences = new Set();

renderConformance({
  suite: "conformance: rendered HTML with the full default configuration matches the reference implementation",
  fixturesDir: "render-full",
  extension: ".html",
  convert: (texy, source) => texy.process(source),
  configure: texy => {
    texy.allowed[Syntax.Emoticon] = true; // fixtures were generated with --emoticon
  },
  knownDivergences,
});
